using Lastlight.Core;
public static class SolarEdges
{
 public static void Run(Definitions d,string output)
 {
  Directory.CreateDirectory(output);void Require(bool v,string m){if(!v)throw new Exception(m);}void Steps(World w,int n){for(int i=0;i<n;i++)w.Step(d);}void Cmd(World w,WorldCommand c){var r=w.Apply(c,d);Require(r.Accepted,r.Message);}void Until(World w,Func<bool> done,int limit){for(int i=0;i<limit&&!done();i++)w.Step(d);Require(done(),"Edge expedition stalled.");w.Validate(d);}
  foreach(bool shield in new[]{false,true})
  {var w=SolarWorldGenerator.Create(d,74219);long leader=w.Colony.People.Keys.First();w.Solar.Stage=2;Cmd(w,new(CommandKind.CampaignAction,DefinitionId:"Custom",Quantity:60,Text:"mode"));Cmd(w,new(CommandKind.CampaignAction,DefinitionId:"Raids",Quantity:0,Text:"setting"));var meal=w.Apply(new(CommandKind.Spawn,DefinitionId:"meal",X:62,Y:67,Quantity:6),d);Require(meal.Accepted,meal.Message);if(shield)Cmd(w,new(CommandKind.Spawn,DefinitionId:"f-cloth",X:62,Y:67));var far=w.Region.Sites.First(s=>s.Kind=="Town"&&s.X==10&&s.Y==10);Cmd(w,new(CommandKind.RegionAction,leader,leader.ToString(),TargetId:far.Id,Rotation:shield?1:0,Text:"depart"));var party=w.Region.Parties.Single();Until(w,()=>party.State=="Outbound",6000);w.Solar.NextFlareAt=w.Tick+World.TicksPerHour*6;w.Solar.FlareAnnounced=false;Until(w,()=>w.Solar.Flares==1,World.TicksPerHour*6+60);Require(w.Solar.Forecasts.Any(f=>f.Kind=="Flare"&&f.Resolved)&&party.State=="Outbound","Forecast travel exposure not exercised.");if(shield)Require(party.Cargo.GetValueOrDefault("f-cloth")==0&&w.Body(leader)!.Wounds.All(q=>q.Kind!="Burn")&&w.Region.History.Any(h=>h.Kind=="FlareShelter"),"Real shield cloth not consumed or traveler injured");else Require(w.Body(leader)!.Wounds.Any(q=>q.Kind=="Burn")&&w.Region.History.Any(h=>h.Kind=="FlareExposure"),"Unshielded travel ignored warning/exposure");SaveStore.Write(Path.Combine(output,shield?"solar-shielded-travel.lastlight":"solar-exposed-travel.lastlight"),w,new(){CameraX=64,CameraY=64,OpenTab="World"},d);}
  Console.WriteLine("PASS I flare edge: six-hour warning, actual provisioned travel, unshielded burns, transported/consumed cloth shielding and persistent hazard cause");
  var politics=SolarWorldGenerator.Create(d,74219);var f=politics.Region.Factions.First();politics.Solar.Claims.Add(new(){Id=politics.Solar.NextId++,FactionId=f.Id,SiteId=politics.Region.HomeSiteId});
  Cmd(politics,new(CommandKind.CampaignAction,TargetId:politics.Solar.Claims[0].Id,Text:"refuse-claim"));politics.Region.Treaties.Add(new(){Id=politics.Region.NextId++,FactionId=f.Id,Kind="Sanctuary",SignedAt=politics.Tick});int strength=f.Strength,wood=f.Reserves["wood"];politics.Solar.NextIncidentAt=0;politics.Danger.RaidsEnabled=true;Steps(politics,30);Require(politics.Danger.Raid.Phase=="Idle"&&f.Strength==strength&&f.Reserves["wood"]==wood,"Director fabricated war against signed diplomacy.");
  politics.Region.Treaties.Clear();politics.Solar.NextIncidentAt=0;politics.Solar.Incidents=0;Steps(politics,30);Require(politics.Danger.Raid.Phase=="Warning"&&f.Strength<strength&&f.Reserves["wood"]<wood&&politics.Solar.History.Any(h=>h.Kind=="Sanctuary conflict"&&h.FactionId==f.Id),"Persistent funded claim did not create a causally budgeted warning.");Console.WriteLine("PASS I03/director: explicit independence grievance, signed peace suppresses claims war, unresolved funded motive consumes faction force/wood and warns through existing combat");
  var recovery=SolarWorldGenerator.Create(d,74219);long patient=recovery.Colony.People.Keys.First();recovery.InflictWound(patient,"left-arm","Cut",5,0,d);recovery.Solar.NextIncidentAt=0;Steps(recovery,30);Require(recovery.Solar.DirectorStatus.Contains("Injured")&&recovery.Solar.History.Count==0&&recovery.Danger.Raid.Phase=="Idle","Director stacked pressure during medical recovery.");Cmd(recovery,new(CommandKind.CampaignAction,DefinitionId:"Disease",Quantity:0,Text:"setting"));Cmd(recovery,new(CommandKind.CampaignAction,DefinitionId:"Stress",Quantity:0,Text:"setting"));Require(recovery.CampaignDiseaseFactor()==0&&recovery.CampaignStressFactor()==0,"Independent hazard controls not authoritative.");Console.WriteLine("PASS I05 recovery/custom: medical recovery visibly defers incidents; disease and social stress settings are independent authoritative controls");
  var migration=SolarWorldGenerator.Create(d,74219);var poor=migration.Region.Factions.First();poor.Reserves["f-parts"]=0;int population=migration.Region.Factions.Sum(f=>f.Population),beforePoor=poor.Population;Cmd(migration,new(CommandKind.CampaignAction,DefinitionId:"Custom",Quantity:2,Text:"mode"));migration.Tick=migration.Solar.NextBoundary-30;Steps(migration,30);Require(migration.Solar.Stage==1&&migration.Solar.Refuges.First(r=>r.FactionId==poor.Id).Level==0&&migration.Region.Factions.Sum(f=>f.Population)==population&&poor.Population==beforePoor-1&&migration.Solar.Refuges.Sum(r=>r.Migrants)==1,"Refuge migration fabricated residents or unfunded shelter.");Console.WriteLine("PASS I02 migration edge: unavailable parts block adaptation; a better funded refuge receives one real summarized resident with population conserved");
  var rejectedProject=SolarWorldGenerator.Create(d,74219);var project=rejectedProject.Solar.Projects.First();long selected=rejectedProject.Colony.People.Keys.First();Require(!rejectedProject.Apply(new(CommandKind.CampaignAction,selected,"Sun",TargetId:rejectedProject.Slice.Ruin.EngineId,Text:"project"),d).Accepted&&project.HostId==0&&project.WorkerId==0&&!project.Active&&rejectedProject.Autonomy.Claims.Count==0,"Rejected finale reserved a worker/host/materials.");Console.WriteLine("PASS I04 prerequisite edge: rejected commissioning creates no worker, host or material reservation");
  var malformed=SolarWorldGenerator.Create(d,74219);malformed.Solar.Luminosity=101;bool rejected=false;try{malformed.Validate(d);}catch(InvalidDataException){rejected=true;}Require(rejected,"Invalid solar measurement accepted.");Console.WriteLine("PASS I integrity: invalid solar measurements and bounded/reference-linked campaign state rejected");
 }
}
